// Erzeugt von tools/gen_content.py aus data/lebenslaeufe/. Nicht von Hand ändern.
using System.Collections.Generic;

namespace BalkanMod.CharacterCreation
{
    internal static class BalkanBackgroundTable
    {
        /// <summary>(Kultur-Id, Option der Charaktererstellung) -> eigener Titel und Text.</summary>
        public static readonly Dictionary<(string Culture, string Option), (string Title, string Text)> Options =
            new Dictionary<(string Culture, string Option), (string Title, string Text)>
        {
            { ("aserai", "aserai_kinsfolk_option"), ("{=balkan_bg_bosniaken_aserai_kinsfolk}Kin of a beg", "{=balkan_bg_bosniaken_aserai_kinsfolk_text}Your family were a lesser branch of an old Bosnian begs' house. Your father's timar paid for a good horse but not for the armour of the heavy cavalry, so he rode with the light horsemen who raid across the frontier.") },
            { ("aserai", "aserai_slave_option"), ("{=balkan_bg_bosniaken_aserai_slave}A kapetan's household", "{=balkan_bg_bosniaken_aserai_slave_text}Your father served in the armed household of a frontier kapetan and rode with his armoured horsemen against Habsburg and Venetian raiders. For his valour he was given land of his own, and then he married your mother.") },
            { ("aserai", "aserai_physician_option"), ("{=balkan_bg_bosniaken_aserai_physician}Physicians", "{=balkan_bg_bosniaken_aserai_physician_text}Your family were respected physicians in the čaršija of Sarajevo. They set bones, treated fevers and mixed remedies from the herbs of the hills. Even the begs sent for them.") },
            { ("aserai", "aserai_farmer_option"), ("{=balkan_bg_bosniaken_aserai_farmer}Valley farmers", "{=balkan_bg_bosniaken_aserai_farmer_text}Your family farmed wheat and plums in a valley along the Bosna. Your father marched with the foot soldiers of the kapetanija when the frontier forts called for men.") },
            { ("aserai", "aserai_herder_option"), ("{=balkan_bg_bosniaken_aserai_herder}Highland herders", "{=balkan_bg_bosniaken_aserai_herder_text}Your family drove their flocks up to the high pastures of the Dinaric mountains every summer and brought them back down to the valleys before the snows.") },
            { ("aserai", "aserai_artisan_option"), ("{=balkan_bg_bosniaken_aserai_artisan}Mahala toughs", "{=balkan_bg_bosniaken_aserai_artisan_text}Your father worked for one of the strongmen who keep order in the poorer mahalas of the town. He settled quarrels over debts, dice and insults, and his heavy stick settled the rest.") },
            { ("bulgarians", "sturgia_companion_option"), ("{=balkan_bg_bulgaren_sturgia_companion}A çeribaşı's household", "{=balkan_bg_bulgaren_sturgia_companion_text}Your father belonged to the household of a voynuk çeribaşı. The voynuks were Christians who served the Sultan in return for freedom from taxes. When the army marched, they brought horses and carried its baggage, and your father rode with them.") },
            { ("bulgarians", "sturgia_trader_option"), ("{=balkan_bg_bulgaren_sturgia_trader}Travelling traders", "{=balkan_bg_bulgaren_sturgia_trader_text}Your family were traders who drove their pack animals from market to market. They knew the roads and the inns and which official had to be paid along the way.") },
            { ("bulgarians", "sturgia_farmer_option"), ("{=balkan_bg_bulgaren_sturgia_farmer}Christian farmers", "{=balkan_bg_bulgaren_sturgia_farmer_text}Your family farmed a small plot in the valley. They paid their dues to the sipahi and the head tax that Christians owed the Sultan, and had just enough left to live on.") },
            { ("bulgarians", "sturgia_artisan_option"), ("{=balkan_bg_bulgaren_sturgia_artisan}Goldsmiths of Chiprovtsi", "{=balkan_bg_bulgaren_sturgia_artisan_text}Your family were gold- and silversmiths in Chiprovtsi, the Catholic town in the northwest. When the uprising of 1688 failed and the town was burned, they fled with what they could carry and started again elsewhere.") },
            { ("bulgarians", "sturgia_hunter_option"), ("{=balkan_bg_bulgaren_sturgia_hunter}Mountain folk", "{=balkan_bg_bulgaren_sturgia_hunter_text}Your family lived in a village high in the mountains, far from the officials of the plain. They kept goats, hunted in the forests and guided travellers over the passes.") },
            { ("bulgarians", "sturgia_vagabond_option"), ("{=balkan_bg_bulgaren_sturgia_vagabond}Friends of the hajduks", "{=balkan_bg_bulgaren_sturgia_vagabond_text}Your family were poor and owned nothing but debts. They carried bread and news to the hajduks in the forests and sold what the hajduks took from the tax collectors. You learned early whom to trust and whom to fear.") },
            { ("germans", "vlandia_retainer_option"), ("{=balkan_bg_deutsche_vlandia_retainer}A count's retainers", "{=balkan_bg_deutsche_vlandia_retainer_text}Your father was steward to an imperial count who had been given lands in the reconquered parts of Hungary. He looked after the estates, settled disputes in the villages and trained the levy. In war he rode with the count's cuirassiers.") },
            { ("germans", "vlandia_merchant_option"), ("{=balkan_bg_deutsche_vlandia_merchant}Burghers", "{=balkan_bg_deutsche_vlandia_merchant_text}Your family were merchants who traded along the Danube. They shipped cloth and iron goods downriver, brought back hides and cattle, and sat in the merchants' guild of their town.") },
            { ("germans", "vlandia_farmer_option"), ("{=balkan_bg_deutsche_vlandia_farmer}Settlers", "{=balkan_bg_deutsche_vlandia_farmer_text}Your family were among the Swabian colonists who took up land along the Danube after the Turks were driven out. They cleared the land, built their farmhouse and had just enough to feed themselves and sell a little. The men served in the militia.") },
            { ("germans", "vlandia_blacksmith_option"), ("{=balkan_bg_deutsche_vlandia_blacksmith}Town smiths", "{=balkan_bg_deutsche_vlandia_blacksmith_text}Your family owned a smithy in Osijek, the garrison town on the Drava. Your father shod the cavalry's horses, had a small voice in the town council and served in the citizens' militia.") },
            { ("germans", "vlandia_hunter_option"), ("{=balkan_bg_deutsche_vlandia_hunter}Hunters", "{=balkan_bg_deutsche_vlandia_hunter_text}Your family lived in a village on the edge of the great oak forests of Slavonia but owned no land. Your father took whatever work he could find and spent long days hunting and trapping, always wary of the lord's gamekeepers.") },
            { ("germans", "vlandia_mercenary_option"), ("{=balkan_bg_deutsche_vlandia_mercenary}A soldier's family", "{=balkan_bg_deutsche_vlandia_mercenary_text}Your father served in one of the Emperor's regiments of foot, men who had marched from one war to the next since the siege of Vienna and never took well to peace. Their musketeers were valued wherever there was fighting. Your mother followed the baggage train and took you along in the wake of bloody campaigns.") },
            { ("greeks", "empire_lanlord_option"), ("{=balkan_bg_griechen_empire_lanlord}A family of notables", "{=balkan_bg_griechen_empire_lanlord_text}Your family were kodjabashis, the leading Christian notables of their town. Your father spoke for the community before the Ottoman officials and collected its taxes for the Porte.") },
            { ("greeks", "empire_merchant_option"), ("{=balkan_bg_griechen_empire_merchant}Ship owners", "{=balkan_bg_griechen_empire_merchant_text}Your family owned a share in a merchant ship. Greek ships carried much of the empire's trade by sea, and you grew up hearing of the harbours of the Aegean.") },
            { ("greeks", "empire_farmer_option"), ("{=balkan_bg_griechen_empire_farmer}Village farmers", "{=balkan_bg_griechen_empire_farmer_text}Your family farmed fields and vines in a village. They paid their dues to the sipahi and the head tax to the Sultan, and in hard years the notables of the village had to plead for them.") },
            { ("greeks", "empire_artisan_option"), ("{=balkan_bg_griechen_empire_artisan}Town craftsmen", "{=balkan_bg_griechen_empire_artisan_text}Your family owned a workshop in a market town. Your father was respected in his craft and kept the accounts of the church.") },
            { ("greeks", "empire_hunter_option"), ("{=balkan_bg_griechen_empire_hunter}Armatoles of the mountains", "{=balkan_bg_griechen_empire_hunter_text}Your father was an armatole in the mountains. He guarded the passes on behalf of the Ottomans and the villages paid him for it, but before that he had lived as a klepht, and he still knew the brigands in the forests by name.") },
            { ("greeks", "empire_vagabond_option"), ("{=balkan_bg_griechen_empire_vagabond}Harbour folk", "{=balkan_bg_griechen_empire_vagabond_text}Your family lived from the harbour of a port town, loading ships, mending nets and running errands for smugglers. You grew up among sailors and learned to talk your way out of trouble.") },
            { ("vlandia", "vlandia_retainer_option"), ("{=balkan_bg_kroaten_vlandia_retainer}A magnate's retainers", "{=balkan_bg_kroaten_vlandia_retainer_text}Your father was the bailiff of a Croatian magnate, one of the great houses like the Draškovićs or the Erdődys. He looked after his lord's estates, settled disputes in the villages and trained the levy. In war he rode with the lord's armoured horse.") },
            { ("vlandia", "vlandia_merchant_option"), ("{=balkan_bg_kroaten_vlandia_merchant}Merchants of Zagreb", "{=balkan_bg_kroaten_vlandia_merchant_text}Your family were merchants in Gradec, the free royal town on the hill of Zagreb. They sent wagons to Carniola, Styria and the Venetian coast and sat in the merchants' guild.") },
            { ("vlandia", "vlandia_farmer_option"), ("{=balkan_bg_kroaten_vlandia_farmer}Frontiersmen", "{=balkan_bg_kroaten_vlandia_farmer_text}Your family held land on the Military Frontier. They owed no labour to any lord, but every man in the house took up his musket when the Turks came across the Una. They had just enough to live on and a little to sell.") },
            { ("vlandia", "vlandia_blacksmith_option"), ("{=balkan_bg_kroaten_vlandia_blacksmith}Town smiths", "{=balkan_bg_kroaten_vlandia_blacksmith_text}Your family owned a smithy in Karlovac, the six-pointed star fortress built in 1579 where the Korana meets the Kupa. Your father had a small voice in the town council and served in the citizens' militia.") },
            { ("vlandia", "vlandia_hunter_option"), ("{=balkan_bg_kroaten_vlandia_hunter}Hunters", "{=balkan_bg_kroaten_vlandia_hunter_text}Your family lived in a village in the forests of Gorski Kotar but owned no land. Your father took whatever work he could find and spent long days in the woods hunting and trapping, always wary of the count's gamekeepers.") },
            { ("vlandia", "vlandia_mercenary_option"), ("{=balkan_bg_kroaten_vlandia_mercenary}Croat horsemen", "{=balkan_bg_kroaten_vlandia_mercenary_text}Your grandfather rode with the Croats, the light horsemen with carbine and pistols who fought for the Emperor across Germany in the Thirty Years' War. Your father followed him into the Emperor's service, and war never let him go. Your mother followed the baggage train and took you along in the wake of bloody campaigns.") },
            { ("ragusa", "empire_lanlord_option"), ("{=balkan_bg_ragusaner_empire_lanlord}A patrician's retainers", "{=balkan_bg_ragusaner_empire_lanlord_text}Your father was a trusted man of a patrician family of Dubrovnik and managed their estates in Konavle. When the Republic called its few horsemen to guard the border, he rode with them.") },
            { ("ragusa", "empire_merchant_option"), ("{=balkan_bg_ragusaner_empire_merchant}Merchants", "{=balkan_bg_ragusaner_empire_merchant_text}Your family were merchants of Dubrovnik who traded between the Ottoman Balkans and Italy. They sent caravans inland to Sarajevo and Belgrade and belonged to the Brotherhood of St Anthony, the fraternity of the city's wealthy commoners.") },
            { ("ragusa", "empire_farmer_option"), ("{=balkan_bg_ragusaner_empire_farmer}Smallholders", "{=balkan_bg_ragusaner_empire_farmer_text}Your family farmed terraced vineyards and olive groves on the Pelješac peninsula. They had just enough to feed themselves and sell a little, and like all subjects of the Republic they served in its militia.") },
            { ("ragusa", "empire_artisan_option"), ("{=balkan_bg_ragusaner_empire_artisan}Artisans", "{=balkan_bg_ragusaner_empire_artisan_text}Your family owned a workshop in Dubrovnik, making cloth, soap or wax candles for the ships. Your father had a small voice in the fraternity of his craft and stood guard on the city walls.") },
            { ("ragusa", "empire_hunter_option"), ("{=balkan_bg_ragusaner_empire_hunter}Foresters", "{=balkan_bg_ragusaner_empire_hunter_text}Your family lived in a village in the hills behind the city but owned no land. Your father took whatever work he could find and spent long days in the hills hunting and trapping, always wary of the Republic's wardens.") },
            { ("ragusa", "empire_vagabond_option"), ("{=balkan_bg_ragusaner_empire_vagabond}Harbour poor", "{=balkan_bg_ragusaner_empire_vagabond_text}Your family were among the poor who crowded the harbour of Dubrovnik and lived from odd jobs on the quays and in the shipyards of Gruž. Sometimes they ran goods for smugglers, and you saw the dark side of life early.") },
            { ("serbs", "sturgia_companion_option"), ("{=balkan_bg_serben_sturgia_companion}A vojvoda's companions", "{=balkan_bg_serben_sturgia_companion_text}Your father belonged to the armed household of a Serbian vojvoda. He sat at his lord's table, looked after his villages and stood at his side in the front rank in battle. When the Patriarch led the people out of Belgrade in 1690, they went with him.") },
            { ("serbs", "sturgia_trader_option"), ("{=balkan_bg_serben_sturgia_trader}River traders", "{=balkan_bg_serben_sturgia_trader_text}Your family were merchants in one of the towns on the Danube and the Sava. They shipped wool, hides, wax and honey upriver to the Habsburg lands and brought back cloth and iron.") },
            { ("serbs", "sturgia_farmer_option"), ("{=balkan_bg_serben_sturgia_farmer}A zadruga's farmers", "{=balkan_bg_serben_sturgia_farmer_text}Your family belonged to a zadruga, a great household of brothers and cousins who worked their land together under one elder. They had just enough to live on and sent their sons when the levy was called.") },
            { ("serbs", "sturgia_artisan_option"), ("{=balkan_bg_serben_sturgia_artisan}Town artisans", "{=balkan_bg_serben_sturgia_artisan_text}Your family owned a workshop in a town, working copper, leather and wool brought in from the villages. Your father had a small voice in his esnaf, the guild of his craft, and served in the town watch.") },
            { ("serbs", "sturgia_hunter_option"), ("{=balkan_bg_serben_sturgia_hunter}Forest folk", "{=balkan_bg_serben_sturgia_hunter_text}Your family wanted nothing to do with pashas or tax collectors. They lived deep in the oak forests of Šumadija, clearing fields for a year or two before moving on, and hunted fox, hare, marten and wolf.") },
            { ("serbs", "sturgia_vagabond_option"), ("{=balkan_bg_serben_sturgia_vagabond}Refugees", "{=balkan_bg_serben_sturgia_vagabond_text}Your family were among the refugees the wars had driven from their villages. They lived in shacks outside the walls of the river towns and took whatever work they could find. Sometimes they ran errands for smugglers and for the men who sold the hajduks' plunder.") },
            { ("turks", "aserai_kinsfolk_option"), ("{=balkan_bg_tuerken_aserai_kinsfolk}Kin of a sipahi", "{=balkan_bg_tuerken_aserai_kinsfolk_text}Your family were a lesser branch of an old sipahi house in Rumelia. Your father's timar paid for a good horse but not for the armour of the heavy cavalry, so he rode with the light horsemen of the Sultan's armies.") },
            { ("turks", "aserai_slave_option"), ("{=balkan_bg_tuerken_aserai_slave}Servants of the Porte", "{=balkan_bg_tuerken_aserai_slave_text}Your father was taken as a boy in the devşirme and raised as a servant of the Porte. He rode with the armoured horse of the Sultan's household, and when he left the service he received land of his own and married your mother.") },
            { ("turks", "aserai_physician_option"), ("{=balkan_bg_tuerken_aserai_physician}Physicians", "{=balkan_bg_tuerken_aserai_physician_text}Your family were respected physicians in a city of Rumelia, schooled in the medicine of the old masters. They set bones and cured the sick, and pashas and kadis sought their advice.") },
            { ("turks", "aserai_farmer_option"), ("{=balkan_bg_tuerken_aserai_farmer}Peasants of Rumelia", "{=balkan_bg_tuerken_aserai_farmer_text}Your family tilled wheat fields on the plains of Rumelia. Your father marched with the azaps, the foot soldiers raised from the villages for the Sultan's campaigns.") },
            { ("turks", "aserai_herder_option"), ("{=balkan_bg_tuerken_aserai_herder}Yörük nomads", "{=balkan_bg_tuerken_aserai_herder_text}Your family were Yörük, nomads who moved their sheep and goats between summer pastures in the mountains and winter camps on the plains, as their ancestors had done since they came from Anatolia.") },
            { ("turks", "aserai_artisan_option"), ("{=balkan_bg_tuerken_aserai_artisan}Back-alley toughs", "{=balkan_bg_tuerken_aserai_artisan_text}Your father worked for a kabadayı, one of the strongmen who keep order in the poorer quarters of the towns. He settled quarrels over debts, dice and insults, and his heavy staff settled the rest.") },
            { ("hungarians", "vlandia_retainer_option"), ("{=balkan_bg_ungarn_vlandia_retainer}A magnate's retainers", "{=balkan_bg_ungarn_vlandia_retainer_text}Your father was the steward of a Hungarian magnate's estates. He looked after the lands, settled disputes in the villages and trained the levy. In war he rode with his lord's armed horsemen.") },
            { ("hungarians", "vlandia_merchant_option"), ("{=balkan_bg_ungarn_vlandia_merchant}Burghers", "{=balkan_bg_ungarn_vlandia_merchant_text}Your family were merchants in a town of the Great Plain. They drove grey cattle on the hoof to the markets of Vienna and Nuremberg and sat in the town's merchants' guild.") },
            { ("hungarians", "vlandia_farmer_option"), ("{=balkan_bg_ungarn_vlandia_farmer}Hajdú peasants", "{=balkan_bg_ungarn_vlandia_farmer_text}Your family were hajdú, whose forefathers Prince Bocskai freed from their lords' jurisdiction and gave land for their service. They had just enough land to live on and a little to sell, and a musket hung above the hearth for when the call to arms came.") },
            { ("hungarians", "vlandia_blacksmith_option"), ("{=balkan_bg_ungarn_vlandia_blacksmith}Town smiths", "{=balkan_bg_ungarn_vlandia_blacksmith_text}Your family owned a smithy in Debrecen, the great market town of the plain. Your father had a small voice in the town council and served in the citizens' militia.") },
            { ("hungarians", "vlandia_hunter_option"), ("{=balkan_bg_ungarn_vlandia_hunter}Hunters", "{=balkan_bg_ungarn_vlandia_hunter_text}Your family lived in a village in the marshes along the Tisza but owned no land. Your father took whatever work he could find and spent long days hunting and fishing in the reeds, always wary of the lord's gamekeepers.") },
            { ("hungarians", "vlandia_mercenary_option"), ("{=balkan_bg_ungarn_vlandia_mercenary}Kuruc fighters", "{=balkan_bg_ungarn_vlandia_mercenary_text}Your father rode with the kuruc of Imre Thököly, the insurgents who fought the Habsburgs and, under Thököly, sided with the Sultan. He never took well to peace. Your mother followed the camp and took you along in the wake of bloody campaigns.") },
            { ("venice", "empire_lanlord_option"), ("{=balkan_bg_venezianer_empire_lanlord}A noble's retainers", "{=balkan_bg_venezianer_empire_lanlord_text}Your father was a trusted man of a noble family of Zadar and managed their estates in the countryside. In war he rode with the cappelletti, the light horsemen the Republic raises among the Dalmatian Croats.") },
            { ("venice", "empire_merchant_option"), ("{=balkan_bg_venezianer_empire_merchant}Merchants", "{=balkan_bg_venezianer_empire_merchant_text}Your family were merchants in Split who shipped Dalmatian wine, oil and salt to Venice. They had a seat in the town council.") },
            { ("venice", "empire_farmer_option"), ("{=balkan_bg_venezianer_empire_farmer}Colonists", "{=balkan_bg_venezianer_empire_farmer_text}Your family took up land behind the coast after the war. They had just enough to feed themselves and sell a little, and the men served in the cranide, as the rural militia is called in Dalmatia.") },
            { ("venice", "empire_artisan_option"), ("{=balkan_bg_venezianer_empire_artisan}Artisans", "{=balkan_bg_venezianer_empire_artisan_text}Your family owned a workshop in a Dalmatian town, building boats, weaving sails or twisting rope. Your father had a small voice in his scuola, the fraternity of his craft, and served in the town militia.") },
            { ("venice", "empire_hunter_option"), ("{=balkan_bg_venezianer_empire_hunter}Foresters", "{=balkan_bg_venezianer_empire_hunter_text}Your family lived in a village in the Zagora hills but owned no land. Your father took whatever work he could find and spent long days hunting and trapping, always wary of the counts' wardens.") },
            { ("venice", "empire_vagabond_option"), ("{=balkan_bg_venezianer_empire_vagabond}Harbour poor", "{=balkan_bg_venezianer_empire_vagabond_text}Your family were among the poor who crowded the harbours of Split and Zadar and took whatever work they could find on the quays. Sometimes they worked for the smugglers of the coast, and you saw the dark side of life early.") },
        };
    }
}
